// ============================================================================
// tb_top : vector-driven testbench for Project 4 v2 (APBTMR-SPEC v1.0)
// ----------------------------------------------------------------------------
// * Instantiates the DUT (module apb_timer: reference copy, a mutant, or a generated RTL)
//   and the reference (module apb_timer_ref) on identical inputs.
// * Reads vectors/all.vec (one line per clock cycle, generated by scripts/gen_vectors.py
//   from the executable spec model) and checks, every cycle:
//     SPEC_MISMATCH : DUT outputs or DUT architectural state != spec-model expected values
//     REF_DIVERGE   : DUT outputs or DUT architectural state != reference instance
//                     (REF_DIVERGE_PORT counts the subset visible on DUT ports)
// * Optionally instantiates one SVA checker (+define+WITH_SVA) connected to the DUT ports
//   and the DUT's architectural state.
//
// Timing (race-free by construction):
//   - PCLK: 10 ns period, rising edges at 5, 15, 25 ... ns. With +define+CLK_START_1NS (the corrected
//     start-up, proven by the time-0 experiment) PCLK is X until 1 ns, so no net carrying PCLK, including
//     the SVA's own input port, has an edge at time 0. Without it, the SVA port net has a z->0 negedge at 0.
//   - All inputs, including PRESETn, change only at falling edges. Reset therefore asserts and
//     releases mid-cycle and always spans at least one rising edge (R-RST-3).
//   - PRESETn goes X->0 at time 0 after #0, so every async-reset process (DUT, reference, SVA)
//     sees the falling edge and all state is defined before any assertion is evaluated.
//   - Checks happen 2 ns after each falling edge, when combinational outputs have settled.
//
// Plusargs: +VEC=<file> (default vectors/all.vec)  +VCD [+VCDFILE=<file>]  +FSDB (needs +define+FSDB)
// Defines : +define+WITH_SVA       hook up module apb_timer_sva (from whichever SVA file is compiled)
//           +define+CLK2STATE      validation fix: declare PCLK as 2-state 'bit' (no time-0 X->0 clock edge)
//           +define+DIAG_T0        validation: report clock events in the first 1 ns and the values sampled there
//           +define+CLK_START_1NS  time-0 experiment: PCLK is X until 1 ns (no time-0 edge on any PCLK net)
//           +define+DIAG_PORTCLK   time-0 experiment: report clock events on u_sva.PCLK (the SVA's own port net)
//           +define+DIAG_SVA_INTERNALS  with DIAG_PORTCLK, sva_claude_1 only: also print its acc/err/rd_acc/mapped
// Every run prints TBCONFIG (clock start-up used) and, in TBSUMMARY, ref_spec_mismatch_cycles: the
// reference instance checked against the spec-model expected values, independently of the DUT.
// Plusargs (validation): +DIVFILE=<file> (list every diverging cycle)  +TRACE_FROM=<ns> +TRACE_TO=<ns>
//           +define+STATE_Q        DUT state registers are named <name>_q (rtl_claude_1/2)
//           +define+FSDB           enable $fsdbDumpfile/$fsdbDumpvars (requires Verdi PLI)
// This file never prints with $error, so SVA failures can be counted unambiguously.
// ============================================================================
`timescale 1ns/1ps

`ifdef STATE_Q
  `define ST(n) dut.n``_q
`else
  `define ST(n) dut.n
`endif

module tb_top;
    // ---------------- stimulus signals ----------------
`ifdef CLK_START_1NS
    logic        PCLK;                          // time-0 experiment E3: PCLK stays X (no edge anywhere) until 1 ns,
    initial #1 PCLK = 1'b0;                     // then X->0 after all time-0 initialization has settled
`elsif CLK2STATE
    bit          PCLK    = 1'b0;                // validation fix: 2-state clock, no X->0 transition at time 0
`else
    logic        PCLK    = 1'b0;                // first-run setting (4-state)
`endif
    logic        PRESETn;                       // X until #0, see initial block
    logic        PSEL    = 1'b0;
    logic        PENABLE = 1'b0;
    logic        PWRITE  = 1'b0;
    logic [7:0]  PADDR   = 8'h0;
    logic [31:0] PWDATA  = 32'h0;

    always #5 PCLK = ~PCLK;

    // ---------------- DUT ----------------
    logic [31:0] PRDATA;
    logic        PREADY, PSLVERR, irq;
    apb_timer dut (.PCLK(PCLK), .PRESETn(PRESETn), .PSEL(PSEL), .PENABLE(PENABLE), .PWRITE(PWRITE),
                   .PADDR(PADDR), .PWDATA(PWDATA), .PRDATA(PRDATA), .PREADY(PREADY),
                   .PSLVERR(PSLVERR), .irq(irq));

    // ---------------- reference ----------------
    logic [31:0] r_PRDATA;
    logic        r_PREADY, r_PSLVERR, r_irq;
    apb_timer_ref ref_i (.PCLK(PCLK), .PRESETn(PRESETn), .PSEL(PSEL), .PENABLE(PENABLE), .PWRITE(PWRITE),
                         .PADDR(PADDR), .PWDATA(PWDATA), .PRDATA(r_PRDATA), .PREADY(r_PREADY),
                         .PSLVERR(r_PSLVERR), .irq(r_irq));

    // ---------------- architectural state probes (spec section 6) ----------------
    wire        d_en     = `ST(en);
    wire        d_mode   = `ST(mode);
    wire        d_ie     = `ST(ie);
    wire [7:0]  d_psc    = `ST(psc);
    wire [15:0] d_shadow = `ST(shadow);
    wire [15:0] d_active = `ST(active);
    wire [15:0] d_count  = `ST(count);
    wire [7:0]  d_pcnt   = `ST(pcnt);
    wire        d_pend   = `ST(pend);
    wire        d_ovf    = `ST(ovf);
    wire [68:0] d_state  = {d_en, d_mode, d_ie, d_psc, d_shadow, d_active, d_count, d_pcnt, d_pend, d_ovf};
    wire [68:0] r_state  = {ref_i.en, ref_i.mode, ref_i.ie, ref_i.psc, ref_i.shadow, ref_i.active,
                            ref_i.count, ref_i.pcnt, ref_i.pend, ref_i.ovf};

    // ---------------- optional SVA checker ----------------
`ifdef WITH_SVA
    apb_timer_sva u_sva (
        .PCLK(PCLK), .PRESETn(PRESETn), .PSEL(PSEL), .PENABLE(PENABLE), .PWRITE(PWRITE),
        .PADDR(PADDR), .PWDATA(PWDATA), .PRDATA(PRDATA), .PREADY(PREADY), .PSLVERR(PSLVERR), .irq(irq),
        .a_en(d_en), .a_mode(d_mode), .a_ie(d_ie), .a_psc(d_psc), .a_shadow(d_shadow),
        .a_active(d_active), .a_count(d_count), .a_pcnt(d_pcnt), .a_pend(d_pend), .a_ovf(d_ovf));
`endif

    // ---------------- validation diagnostics (all off by default) ----------------
`ifdef DIAG_T0
    // Reports any clock event in the first 1 ns and the SAMPLED values an assertion clocked on
    // both PCLK edges would see there (same clocking event as sva_claude_1's OCLK checks).
    bit t0_window = 1'b1;
    initial #1 t0_window = 1'b0;
    c_diag_t0_clock_event: cover property (@(posedge PCLK or negedge PCLK) t0_window)
        $display("TBDIAG clock event at time %0t, PCLK now=%b; sampled: PREADY=%b PSLVERR=%b PSEL=%b PENABLE=%b PRDATA=%h PRESETn=%b irq=%b",
                 $time, PCLK, $sampled(PREADY), $sampled(PSLVERR), $sampled(PSEL), $sampled(PENABLE),
                 $sampled(PRDATA), $sampled(PRESETn), $sampled(irq));
    initial #1 $display("TBDIAG time-0 diagnostic active; values at 1 ns: PREADY=%b PSLVERR=%b PRDATA=%h", PREADY, PSLVERR, PRDATA);
`endif
`ifdef DIAG_PORTCLK
`ifdef WITH_SVA
    // Watches the clock AS SEEN BY THE SVA INSTANCE (its own 4-state input-port net), with the same
    // both-edge clocking event as sva_claude_1's OCLK checks, and prints the values those checks sample.
    bit pd_window = 1'b1;
    initial #2 pd_window = 1'b0;
    c_diag_sva_port_clock: cover property (@(posedge u_sva.PCLK or negedge u_sva.PCLK) pd_window)
        $display("TBDIAG2 SVA-port clock event at %0t: u_sva.PCLK now=%b, tb PCLK now=%b | sampled at u_sva ports: PREADY=%b PSLVERR=%b PSEL=%b PENABLE=%b PWRITE=%b PRESETn=%b",
                 $time, u_sva.PCLK, PCLK, $sampled(u_sva.PREADY), $sampled(u_sva.PSLVERR), $sampled(u_sva.PSEL),
                 $sampled(u_sva.PENABLE), $sampled(u_sva.PWRITE), $sampled(u_sva.PRESETn));
`ifdef DIAG_SVA_INTERNALS
    // sva_claude_1 only: the internal nets used by APB8_pslverr / APB8_pslverr_nonacc / APB7_prdata_zero
    c_diag_sva_internals: cover property (@(posedge u_sva.PCLK or negedge u_sva.PCLK) pd_window)
        $display("TBDIAG2 SVA-internal sampled at %0t: acc=%b err=%b rd_acc=%b mapped=%b PRDATA=%h",
                 $time, $sampled(u_sva.acc), $sampled(u_sva.err), $sampled(u_sva.rd_acc), $sampled(u_sva.mapped),
                 $sampled(u_sva.PRDATA));
`endif
`endif
`endif
    // +TRACE_FROM=<ns> +TRACE_TO=<ns> : print every change of the interrupt path, DUT vs reference
    integer trace_from = -1, trace_to = -1;
    initial begin
        void'($value$plusargs("TRACE_FROM=%d", trace_from));
        void'($value$plusargs("TRACE_TO=%d", trace_to));
    end
    always @(irq or r_irq or d_pend or ref_i.pend or d_ovf or ref_i.ovf or d_count or ref_i.count or PCLK)
        if (trace_from >= 0 && $time >= trace_from && $time <= trace_to)
            $display("TBTRACE t=%0t PCLK=%b PSEL=%b PENABLE=%b PWRITE=%b PADDR=%h PWDATA=%h | DUT irq=%b pend=%b ovf=%b count=%0d | REF irq=%b pend=%b ovf=%b count=%0d",
                     $time, PCLK, PSEL, PENABLE, PWRITE, PADDR, PWDATA, irq, d_pend, d_ovf, d_count,
                     r_irq, ref_i.pend, ref_i.ovf, ref_i.count);

    // ---------------- waveform dumping ----------------
    string vcdfile;
    initial begin
        if ($test$plusargs("VCD")) begin
            if (!$value$plusargs("VCDFILE=%s", vcdfile)) vcdfile = "waves.vcd";
            $dumpfile(vcdfile);
            $dumpvars(0, tb_top);
        end
`ifdef FSDB
        if ($test$plusargs("FSDB")) begin
            $fsdbDumpfile("waves.fsdb");
            $fsdbDumpvars(0, tb_top, "+all");
        end
`endif
    end

    // ---------------- vector player and checker ----------------
    string       vecfile;
    integer      fd, code;
    reg   [31:0] t_id, t_rst, t_psel, t_pen, t_pwr, t_addr, t_wdata;
    reg   [31:0] e_prdata, e_pslverr, e_pready, e_irq;
    reg   [31:0] e_en, e_mode, e_ie, e_psc, e_shadow, e_active, e_count, e_pcnt, e_pend, e_ovf;
    reg   [68:0] e_state;
    integer      cyc, cur_tid;
    integer      n_spec, n_div, n_div_port, n_refspec;
    integer      first_div_cyc, first_div_tid;
    time         first_div_time;
    localparam integer MAXPRINT = 20;
    bit          spec_bad, div_state, div_port, ref_bad;
    string       divfile;
    integer      divfd;

    initial begin
        $timeformat(-9, 0, "ns", 0);           // all %t below print as <integer>ns
        n_spec = 0; n_div = 0; n_div_port = 0; n_refspec = 0; cyc = 0; cur_tid = -1;
`ifdef CLK_START_1NS
        $display("TBCONFIG clock_startup=CLK_START_1NS");
`elsif CLK2STATE
        $display("TBCONFIG clock_startup=CLK2STATE");
`else
        $display("TBCONFIG clock_startup=LOGIC_INIT");
`endif
        first_div_cyc = -1; first_div_tid = -1; first_div_time = 0;
        if (!$value$plusargs("VEC=%s", vecfile)) vecfile = "vectors/all.vec";
        divfd = 0;
        if ($value$plusargs("DIVFILE=%s", divfile)) divfd = $fopen(divfile, "w");   // every diverging cycle: cyc tid port state
        fd = $fopen(vecfile, "r");
        if (fd == 0) begin
            $display("TBFATAL cannot open vector file %0s", vecfile);
            $finish;
        end
        #0 PRESETn = 1'b0;                       // X->0 edge at time 0 (see header)
`ifdef CLK_START_1NS
        @(posedge PCLK);                         // skip the 1 ns X->0 edge so vectors start at 10 ns exactly as before
`endif
        forever begin
            @(negedge PCLK);
            code = $fscanf(fd, "%h %h %h %h %h %h %h %h %h %h %h %h %h %h %h %h %h %h %h %h %h\n",
                           t_id, t_rst, t_psel, t_pen, t_pwr, t_addr, t_wdata,
                           e_prdata, e_pslverr, e_pready, e_irq,
                           e_en, e_mode, e_ie, e_psc, e_shadow, e_active, e_count, e_pcnt, e_pend, e_ovf);
            if (code != 21) break;
            if (t_id != cur_tid) begin
                cur_tid = t_id;
                $display("TBTEST tid=%0d time=%0t cyc=%0d", t_id, $time, cyc);
            end
            // drive this cycle's inputs (mid-cycle)
            PRESETn = t_rst[0];
            PSEL    = t_psel[0];
            PENABLE = t_pen[0];
            PWRITE  = t_pwr[0];
            PADDR   = t_addr[7:0];
            PWDATA  = t_wdata;
            #2;
            // ---- check against the spec-model expected values ----
            e_state  = {e_en[0], e_mode[0], e_ie[0], e_psc[7:0], e_shadow[15:0], e_active[15:0],
                        e_count[15:0], e_pcnt[7:0], e_pend[0], e_ovf[0]};
            spec_bad = (PRDATA !== e_prdata) || (PSLVERR !== e_pslverr[0]) || (PREADY !== e_pready[0]) ||
                       (irq !== e_irq[0]) || (d_state !== e_state);
            if (spec_bad) begin
                n_spec = n_spec + 1;
                if (n_spec <= MAXPRINT)
                    $display("TBMSG SPEC_MISMATCH time=%0t cyc=%0d tid=%0d got(PRDATA=%h PSLVERR=%b PREADY=%b irq=%b state=%h) exp(PRDATA=%h PSLVERR=%b PREADY=%b irq=%b state=%h)",
                             $time, cyc, t_id, PRDATA, PSLVERR, PREADY, irq, d_state,
                             e_prdata, e_pslverr[0], e_pready[0], e_irq[0], e_state);
            end
            // ---- the reference instance itself against the spec-model expected values ----
            ref_bad = (r_PRDATA !== e_prdata) || (r_PSLVERR !== e_pslverr[0]) || (r_PREADY !== e_pready[0]) ||
                      (r_irq !== e_irq[0]) || (r_state !== e_state);
            if (ref_bad) begin
                n_refspec = n_refspec + 1;
                if (n_refspec <= MAXPRINT)
                    $display("TBMSG REF_SPEC_MISMATCH time=%0t cyc=%0d tid=%0d", $time, cyc, t_id);
            end
            // ---- differential check against the reference instance ----
            div_port  = (PRDATA !== r_PRDATA) || (PSLVERR !== r_PSLVERR) || (PREADY !== r_PREADY) || (irq !== r_irq);
            div_state = (d_state !== r_state);
            if (div_port || div_state) begin
                n_div = n_div + 1;
                if (div_port) n_div_port = n_div_port + 1;
                if (divfd != 0) $fwrite(divfd, "%0d %0d %0d %0d\n", cyc, t_id, div_port, div_state);
                if (first_div_cyc < 0) begin
                    first_div_cyc = cyc; first_div_tid = t_id; first_div_time = $time;
                end
                if (n_div <= MAXPRINT)
                    $display("TBMSG REF_DIVERGE time=%0t cyc=%0d tid=%0d port=%0d state=%0d dut(PRDATA=%h irq=%b PSLVERR=%b state=%h) ref(PRDATA=%h irq=%b PSLVERR=%b state=%h)",
                             $time, cyc, t_id, div_port, div_state, PRDATA, irq, PSLVERR, d_state,
                             r_PRDATA, r_irq, r_PSLVERR, r_state);
            end
            cyc = cyc + 1;
        end
        $display("TBSUMMARY vecfile=%0s cycles=%0d spec_mismatch_cycles=%0d ref_diverge_cycles=%0d ref_diverge_port_cycles=%0d first_diverge_cyc=%0d first_diverge_tid=%0d first_diverge_time=%0t ref_spec_mismatch_cycles=%0d",
                 vecfile, cyc, n_spec, n_div, n_div_port, first_div_cyc, first_div_tid, first_div_time, n_refspec);
        $fclose(fd);
        if (divfd != 0) $fclose(divfd);
        #20 $finish;
    end
endmodule
